"use client";
import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import axiosInstance from "@/utils/axiosIntance";
import maleImageHuman from "../../../public/images/human.webp";
import femaleImageHuman from "../../../public/images/female-human.webp";
import maleImageElf from "../../../public/images/elf.webp";
import femaleImageElf from "../../../public/images/female-elf.webp";
import maleImageDwarf from "../../../public/images/dwarf.png";
import femaleImageDwarf from "../../../public/images/female-dwarf.webp";
import maleImageOgre from "../../../public/images/orc.png";
import femaleImageOgre from "../../../public/images/female-orc.webp";

export default function CharacterCreation() {
  const router = useRouter();
  const [characterName, setCharacterName] = useState("");
  const [gender, setGender] = useState("masculino");
  const [selectedRace, setSelectedRace] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [racesData, setRacesData] = useState<any[]>([]);
  const [loadingRaces, setLoadingRaces] = useState(true);

  const maleImages = {
    humano: maleImageHuman,
    elfo: maleImageElf,
    anao: maleImageDwarf,
    ogro: maleImageOgre,
  };

  const femaleImages = {
    humana: femaleImageHuman,
    elfa: femaleImageElf,
    ana: femaleImageDwarf,
    ogra: femaleImageOgre,
  };

  useEffect(() => {
    const fetchRaces = async () => {
      try {
        setLoadingRaces(true);
        const response = await axiosInstance.get("/races");
        const rawRacesObject = response.data.data;

        if (
          rawRacesObject &&
          typeof rawRacesObject === "object" &&
          !Array.isArray(rawRacesObject)
        ) {
          const fetchedRacesArray = Object.values(rawRacesObject);

          const racesWithImages = fetchedRacesArray.map((race: any) => {
            const nomeMasculino = race.nome_masculino?.toLowerCase();
            const nomeFeminino = race.nome_feminino?.toLowerCase();

            return {
              ...race,
              imagem_masculina_url:
                race.imagem_masculina_url ||
                (nomeMasculino as keyof typeof maleImages) ||
                "",
              imagem_feminina_url:
                race.imagem_feminina_url || [
                  nomeFeminino as keyof typeof femaleImages,
                ] ||
                "",
            };
          });

          setRacesData(racesWithImages);

          if (racesWithImages.length > 0) {
            setSelectedRace((racesWithImages[0] as { id: string }).id);
          }
        } else {
          setErrorMessage("Formato de dados inesperado da API de raças.");
        }
      } catch (error) {
        console.error("Erro ao carregar as raças:", error);
        setErrorMessage(
          "Erro ao carregar as raças. Tente novamente mais tarde."
        );
      } finally {
        setLoadingRaces(false);
      }
    };

    fetchRaces();
  }, []);

  const currentRace = racesData.find((race) => race.id === selectedRace);

  console.log(currentRace);

  const currentRaceDescription = currentRace
    ? gender === "masculino"
      ? currentRace.descricao_masculina
      : currentRace.descricao_feminina
    : "Selecione uma raça para ver a descrição.";

  const currentRaceImage = currentRace
    ? gender === "masculino"
      ? currentRace.imagem_masculina_url
      : currentRace.imagem_feminina_url
    : null;

  async function CreateCharacter(characterDetails: {
    name: string;
    gender: string;
    id_race: string;
  }) {
    try {
      const response = await axiosInstance.post(
        "/characters",
        characterDetails
      );
      alert(`Personagem "${characterDetails.name}" criado com sucesso!`);
      router.replace("/dashboard");
    } catch (error: any) {
      console.error("Erro ao criar personagem:", error);
      setErrorMessage(
        error.response?.data?.message ||
          "Erro ao criar personagem. Verifique o nome e tente novamente."
      );
    }
  }

  const handleConfirm = (event: React.FormEvent) => {
    event.preventDefault();
    setErrorMessage("");

    if (characterName.trim() === "") {
      setErrorMessage("Por favor, digite o nome do personagem.");
      return;
    }

    if (!selectedRace) {
      setErrorMessage("Por favor, selecione uma raça.");
      return;
    }

    const characterData = {
      name: characterName,
      gender,
      id_race: selectedRace,
    };

    CreateCharacter(characterData);
  };

  if (loadingRaces) {
    return (
      <div
        className="flex items-center justify-center min-h-screen bg-cover bg-center"
        style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
      >
        <div className="text-white text-3xl">Carregando raças...</div>
      </div>
    );
  }

  if (errorMessage && racesData.length === 0) {
    return (
      <div
        className="flex items-center justify-center min-h-screen bg-cover bg-center"
        style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
      >
        <div className="text-red-500 text-3xl text-center">
          {errorMessage}
          <p className="text-xl mt-4">Por favor, recarregue a página.</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex items-center justify-center min-h-screen bg-cover bg-center"
      style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
    >
      <div className="bg-[#292018] p-8 rounded-lg shadow-xl w-[600px] border-[#F3B43F] border-4 font-imFeel text-white">
        <h2 className="text-4xl text-center text-[#F3B43F] mb-6">
          Escolha sua Raça
        </h2>

        <form onSubmit={handleConfirm}>
          <div className="mb-4">
            <input
              type="text"
              id="characterName"
              className="w-full px-4 py-2 bg-[#DFC492] text-black rounded-md focus:outline-none focus:ring-2 focus:ring-[#F3B43F] text-xl"
              placeholder="Digite o nome do seu personagem"
              value={characterName}
              onChange={(e) => setCharacterName(e.target.value)}
              maxLength={20}
            />
          </div>

          <div className="mb-6 flex items-center justify-center space-x-8">
            {[
              { label: "Masculino", value: "masculino" },
              { label: "Feminino", value: "feminino" },
            ].map(({ label, value }) => (
              <label
                key={value}
                className="flex items-center cursor-pointer text-2xl"
              >
                <input
                  type="radio"
                  name="gender"
                  value={value}
                  checked={gender === value}
                  onChange={() => setGender(value)}
                  className="hidden"
                />
                <span className="w-6 h-6 border-2 border-[#F3B43F] rounded-full flex items-center justify-center mr-2">
                  {gender === value && (
                    <span className="w-3 h-3 bg-[#F3B43F] rounded-full"></span>
                  )}
                </span>
                {label}
              </label>
            ))}
          </div>

          <div className="grid grid-cols-4 gap-4 mb-6">
            {racesData.map((race) => (
              <div
                key={race.id}
                className={`relative p-2 rounded-lg cursor-pointer transition-all duration-200 ${
                  selectedRace === race.id
                    ? "border-4 border-[#F3B43F] bg-[#3a2f24]"
                    : "border-4 border-transparent hover:border-[#F3B43F]/50"
                }`}
                onClick={() => setSelectedRace(race.id)}
              >
                <div
                  className="w-24 h-24 mx-auto mb-2 bg-gray-700 rounded-full overflow-hidden flex items-center justify-center"
                  style={{
                    backgroundImage: `url(${
                      gender === "masculino"
                        ? race.imagem_masculina_url
                        : race.imagem_feminina_url
                    })`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                  }}
                ></div>
                <p className="text-center text-xl text-[#F3B43F]">
                  {gender === "masculino"
                    ? race.nome_masculino
                    : race.nome_feminino}
                </p>
              </div>
            ))}
          </div>

          <div className="bg-[#DFC492] border-2 border-[#F3B43F] p-4 rounded-md mb-6 h-32 flex items-center justify-center text-center">
            <p className="text-lg text-[#1f1813] leading-relaxed">
              {currentRaceDescription}
            </p>
          </div>

          {errorMessage && (
            <p className="text-red-500 text-center mb-4 text-xl">
              {errorMessage}
            </p>
          )}

          <div className="flex justify-center">
            <button
              type="submit"
              className="w-[258px] h-[51px] bg-[#8D6825] font-imFeel text-white text-4xl hover:bg-gradient-to-b rounded-2xl cursor-pointer hover:to-[#8D6825] hover:from-[#684424] border-[#F3B43F] border-4 transition-all duration-200"
            >
              CONFIRMAR
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
